import React from 'react';

const ReadyOrders = () => {
  // Sample ready orders data
  const readyOrders = [
    {
      id: 1,
      orderNumber: 'ORD-001',
      customerName: 'John Smith',
      items: ['Burger', 'Fries', 'Coke'],
      total: '$12.99',
      readyTime: '2:45 PM',
      status: 'ready'
    },
    {
      id: 2,
      orderNumber: 'ORD-002',
      customerName: 'Sarah Johnson',
      items: ['Pizza', 'Salad'],
      total: '$18.50',
      readyTime: '2:47 PM',
      status: 'ready'
    },
    {
      id: 3,
      orderNumber: 'ORD-003',
      customerName: 'Mike Wilson',
      items: ['Sandwich', 'Soup', 'Coffee'],
      total: '$15.75',
      readyTime: '2:50 PM',
      status: 'ready'
    },
    {
      id: 4,
      orderNumber: 'ORD-004',
      customerName: 'Emily Davis',
      items: ['Pasta', 'Garlic Bread'],
      total: '$16.25',
      readyTime: '2:52 PM',
      status: 'ready'
    },
    {
      id: 5,
      orderNumber: 'ORD-005',
      customerName: 'David Brown',
      items: ['Chicken Wings', 'Fries', 'Beer'],
      total: '$22.00',
      readyTime: '2:55 PM',
      status: 'ready'
    },
    {
      id: 6,
      orderNumber: 'ORD-006',
      customerName: 'Lisa Anderson',
      items: ['Tacos', 'Rice', 'Beans'],
      total: '$14.99',
      readyTime: '2:58 PM',
      status: 'ready'
    },
    {
      id: 7,
      orderNumber: 'ORD-007',
      customerName: 'Tom Garcia',
      items: ['Steak', 'Mashed Potatoes', 'Wine'],
      total: '$28.50',
      readyTime: '3:00 PM',
      status: 'ready'
    },
    {
      id: 8,
      orderNumber: 'ORD-008',
      customerName: 'Anna Martinez',
      items: ['Fish & Chips', 'Coleslaw'],
      total: '$19.99',
      readyTime: '3:02 PM',
      status: 'ready'
    }
  ];

  return (
    <div className="w-full">
      <h2 className="text-2xl xl:text-6xl font-bold text-black mb-6 text-center">
        Ready Orders
      </h2>
      
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-4 gap-4 xl:gap-6">
        {readyOrders.map((order) => (
          <div 
            key={order.id} 
            className="bg-white border-2 border-gray-300 rounded-lg p-4 xl:p-6 shadow-md hover:shadow-lg transition-shadow flex-grow flex flex-col"
          >
            {/* Order Header */}
            <div className="flex justify-between items-start mb-3">
              <div className="text-lg xl:text-3xl font-bold text-black">
                {order.orderNumber}
              </div>
              <div className="bg-green-500 text-white px-2 py-1 rounded text-xs xl:text-sm font-semibold">
                READY
              </div>
            </div>

            {/* Customer Name */}
            <div className="text-base xl:text-2xl font-semibold text-gray-800 mb-2">
              {order.customerName}
            </div>

            {/* Items List */}
            <div className="flex-grow mb-3">
              <div className="text-sm xl:text-lg text-gray-600">
                {order.items.map((item, index) => (
                  <div key={index} className="mb-1">
                    • {item}
                  </div>
                ))}
              </div>
            </div>

            {/* Order Footer */}
            <div className="border-t border-gray-200 pt-3 mt-auto">
              <div className="flex justify-between items-center">
                <div className="text-sm xl:text-xl font-semibold text-gray-700">
                  Total: {order.total}
                </div>
                <div className="text-xs xl:text-lg text-gray-500">
                  {order.readyTime}
                </div>
              </div>
            </div>

            {/* Action Button */}
            <button className="w-full mt-3 bg-green-600 hover:bg-green-700 text-white py-2 xl:py-3 rounded-lg font-semibold text-sm xl:text-lg transition-colors">
              Mark as Collected
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ReadyOrders;
